import json
from collections import Counter

data = json.load(open('/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/held-out-4/play/users/u010/system/state/workspace/programs/task-250225e5.json'))
test_input = data['test'][1]

print(f"Test input shape: {len(test_input)}x{len(test_input[0])}")
print("\nTest input:")
for r, row in enumerate(test_input):
    print(f"  Row {r}: {row}")

# Identify background
bg_count = Counter(cell for row in test_input for cell in row)
bg = max(bg_count.keys(), key=lambda k: bg_count[k])
print(f"\nBackground color: {bg} (count: {bg_count[bg]})")

# The test input has 0s in bottom region - find where they are
for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if test_input[r][c] == 0:
            print(f"0 found at ({r}, {c})")

# Let's verify the pattern extraction
# Pattern is in top half (non-background, non-0)
pattern_cells = []
for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if test_input[r][c] != bg and test_input[r][c] != 0:
            pattern_cells.append((r, c))

if pattern_cells:
    rows = [c[0] for c in pattern_cells]
    cols = [c[1] for c in pattern_cells]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)
    print(f"\nPattern bbox: rows {min_r}-{max_r}, cols {min_c}-{max_c}")

    pattern = [[test_input[r][c] for c in range(min_c, max_c + 1)] for r in range(min_r, max_r + 1)]
    print(f"Pattern ({len(pattern)}x{len(pattern[0])}):")
    for row in pattern:
        print(f"  {row}")

    pattern_colors = set(c for row in pattern for c in row)
    pattern_colors.discard(bg)  # Remove background from pattern colors
    pattern_colors.discard(0)
    print(f"Pattern colors: {pattern_colors}")

# Target region (where 0s are)
target_zones = {}
for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if test_input[r][c] == 0:
            zone_key = (r // 3, c // 4)  # Group by potential 3x4 blocks
            if zone_key not in target_zones:
                target_zones[zone_key] = []
            target_zones[zone_key].append((r, c))

print(f"\nTarget zones with 0s:")
for zone_key, cells in target_zones.items():
    print(f"  Zone {zone_key}: {cells}")

